import torch


def run(x):
    return torch.bitwise_not(x)


def gen_inputs(ctx, device):
    shape = tuple(ctx["x__shape"])
    dtype = ctx["x__dtype"]
    if isinstance(dtype, str):
        dtype = getattr(torch, dtype.replace("torch.", ""))
    if dtype == torch.bool:
        x = torch.randint(0, 2, size=shape, dtype=dtype, device="cpu").to(device)
    else:
        x = torch.randint(low=-0x7FFF, high=0x7FFF, size=shape, dtype=dtype, device="cpu").to(device)
    return {"x": x}
